#include <bits/stdc++.h>
using namespace std;
class Solution {public:int minimumObstacles(vector<vector<int>>& grid){int m=grid.size(),n=grid[0].size();vector<vector<int>> d(m,vector<int>(n,INT_MAX));deque<pair<int,int>> q;q.push_front({0,0});d[0][0]=0;int dr[]={1,-1,0,0},dc[]={0,0,1,-1};while(!q.empty()){auto p=q.front();q.pop_front();int r=p.first,c=p.second;for(int z=0;z<4;++z){int x=r+dr[z],y=c+dc[z];if(x<0||x>=m||y<0||y>=n)continue;int w=grid[x][y];if(d[r][c]+w<d[x][y]){d[x][y]=d[r][c]+w;if(w)q.push_back({x,y});else q.push_front({x,y});}}}return d[m-1][n-1];}};
